from pathlib import Path
import json
root=Path.cwd(); dest=root/'outputs/Design_Ref_Analyse_V01'; records=json.loads((dest/'fiches_references.json').read_text(encoding='utf-8'))
text='MESURES DE REPÈRE — DESIGN WOR\nVersion 01 — 13 octobre 2026\n\nOrigine haut gauche. Limites inclusives. Les composantes détectées ne sont pas des blocs sémantiques ; une lettre intérieure ou un chart peut être détecté séparément.\n\n'
for r in records:
 text+=r['file']+' — '+str(r['width'])+' × '+str(r['height'])+' — '+r['role']+'\n'+r['observation']+'\n'
 for key in ['composants_rouges','composants_verts']:
  for c in sorted(r[key],key=lambda c:c['pixels'],reverse=True)[:8]:
   x0,y0,x1,y1=c['bbox_xyxy_inclusive']; text+=f'  {key} : ({x0},{y0}) → ({x1},{y1}), boîte {x1-x0+1} × {y1-y0+1} px, surface de masque {c["pixels"]} px.\n'
 for k,p in r['palette_mesuree'].items():
  text+=f'  {k} : {p["percent"]}% ; RGB le plus fréquent : '+(p['top_rgb'][0]['hex'] if p['top_rgb'] else 'aucun')+'\n'
 text+='\n'
(dest/'Mesures_et_observations_62_references.txt').write_text(text,encoding='utf-8')
guide=(dest/'Connaissance_Design_WOR.txt').read_text(encoding='utf-8').replace('Voir inventaire.json pour le décompte vérifié','44 images de 1350 px de haut et 18 images de 1440 px de haut. Voir inventaire.json pour le décompte vérifié')
guide+='\n15. QUELQUES MESURES RASTER EXACTES\n\nSlide-1 (6).jpg : composante rouge principale (212,118) → (779,221), boîte 568 × 104 px ; 31 906 pixels de rouge dans cette composante. RGB rouge le plus fréquent du masque entier : #FE0000 (3 400 pixels). Blanc fréquent : #FCFCFC. Bande blanche candidate haute y=17–89, puis y=134–204 ; les autres fragments peuvent être des jambages.\n\nSlide-3.jpg : composante rouge principale (297,120) → (965,220), boîte 669 × 101 px ; 42 295 pixels du masque. Bande de lettres hautes y=139–199 puis y=236–295 : écart entre débuts 97 px, espace de 36 lignes de pixels entre les bandes. Blanc de footer détecté dans la zone gauche y=1356–1375 ; la totalité des ascendants n’est pas garantie par le seuil de comptage. Rouge le plus fréquent #FC0001. Blanc fréquent #FFFFFF et #FFF2F2.\n\nSlide-5 (2).jpg : composante de cartouche (277,102) → (683,174), boîte 407 × 73 px ; 17 544 pixels de masque. Une autre composante (941,863) → (1025,943) correspond au pictogramme rouge de la feuille, pas à un cartouche de texte. Rouge fréquent #FF0202 ; vert fréquent #30FF0F.\n\nSlide-2 (10).jpg : grande bande blanche candidate y=75–301, liée au panneau de question. Les rouges sont des composantes de lettres séparées ; les fusionner aveuglément en une carte rouge serait une erreur. Rouge fréquent #E80000 ; blanc fréquent #FFFFFF.\n\nLes mesures de tous les autres fichiers sont dans Mesures_et_observations_62_references.txt et mesures_pixels.json.\n'
(dest/'Connaissance_Design_WOR.txt').write_text(guide,encoding='utf-8')
(root/'REFERENCE_DESIGN_WOR.txt').write_text('BASE DE CONNAISSANCE DESIGN WOR\n\nRéférences visuelles : Design REF (62 JPEG analysés le 13 octobre 2026).\nGuide de production : outputs/Design_Ref_Analyse_V01/Connaissance_Design_WOR.txt\nAtlas avec 62 fiches et inspecteur de pixels : outputs/Design_Ref_Analyse_V01/Atlas_Design_WOR.html\nMesures détaillées : outputs/Design_Ref_Analyse_V01/Mesures_et_observations_62_references.txt\nDonnées : inventaire.json, mesures_pixels.json, fiches_references.json dans le même dossier.\n\nPour les futurs carrousels de ce projet, lire ce guide et inspecter les références choisies avant création. Distinguer les mesures exactes des estimations ; ne pas prétendre avoir identifié la fonte originale. Les suffixes de fichiers mélangent parfois les invités ; contrôler identité et CTA. Préserver les références et versions précédentes.\n',encoding='utf-8')
print('Guide enrichi et index local sauvegardé')
